/**
 * Did the provider REJECT the credential, as opposed to failing to answer?
 *
 * The reference tests for invalid_grant (session.ts: isDeadToken), which is
 * what Auth0 and every other OAuth server returns for a retired refresh token.
 * That string is checked wherever it lands — a field, or the body text.
 *
 * A 401/403 counts too. This layer has already turned the response into an
 * AppError by the time it arrives, and its `kind: 'auth'` IS "the provider
 * refused this credential" — the body text may have been reduced to a generic
 * message on the way. Matching only the string left a rejected token looking
 * like a flaky network, so the vault survived and every relaunch re-tried a
 * credential that could never work again.
 */
function isDeadToken(e: unknown): boolean {
  const err = e as {
    code?: unknown;
    error?: unknown;
    message?: unknown;
    kind?: unknown;
    status?: unknown;
    apiMessage?: unknown;
  } | null;
  if (err?.code === 'invalid_grant' || err?.error === 'invalid_grant') return true;
  if (err?.kind === 'auth' || err?.status === 400 || err?.status === 401 || err?.status === 403)
    return true;
  // Only actual strings are worth sniffing. String() over an unknown yields
  // "[object Object]" for any object (Sonar S6551), which can never contain
  // 'invalid_grant' but WILL mask the fields that might: an error whose
  // message is an object used to contribute noise instead of nothing.
  const text = (v: unknown): string => (typeof v === 'string' ? v : '');
  return /invalid_grant/i.test([text(err?.message), text(err?.apiMessage), text(e)].join(' '));
}

